package com.santhosh.dashboard.model; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="security_events") public class SecurityEvent { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private LocalDateTime timestamp; private String source; private String eventId; private String hostname; private String severity; @Column(length=4000) private String message; private String category; @Column(length=4000) private String metadata; public SecurityEvent(){} public SecurityEvent(LocalDateTime t,String s,String e,String h,String sev,String m,String c,String md){timestamp=t;source=s;eventId=e;hostname=h;severity=sev;message=m;category=c;metadata=md;} public Long getId(){return id;} public LocalDateTime getTimestamp(){return timestamp;} public String getSource(){return source;} public String getEventId(){return eventId;} public String getHostname(){return hostname;} public String getSeverity(){return severity;} public String getMessage(){return message;} public String getCategory(){return category;} public String getMetadata(){return metadata;} }
